Комплексы автоматизации подземных стационарных установок, комплексы автоматизации и роботизации технологических установок\nНормативный срок службы: 4 лет.","level":3},{"id":"code-47060","kind":"paragraph","label":"47060","text":"47060 — Средства автоматизации забойного оборудования (очистных узкозахватных комбайнов, струговых установок, проходческих комбайнов, нарезных, угле- и породопогрузочных машин, бурильных станков, механизированной крепи)\nНормативный срок службы: 3 лет.","level":3},{"id":"code-47061","kind":"paragraph","label":"47061","text":"47061 — Оборудование лабораторий испытательных нефтебаз, в том числе печь муфельная, аппарат для определения коксуемости, инфракрасный спектрометр, хроматограф и другое\nНормативный срок службы: 5 лет.","level":3},{"id":"code-47062","kind":"paragraph","label":"47062","text":"47062 — Приборы учета расхода газа\nНормативный срок службы: 8 лет.","level":3},{"id":"code-47063","kind":"paragraph","label":"47063","text":"47063 — Приборы учета расхода воды, тепла, электроэнергии\nНормативный срок службы: 9 лет.","level":3},{"id":"code-47064","kind":"paragraph","label":"47064","text":"47064 — Регистры уровня топлива\nНормативный срок службы: 4 лет.","level":3},{"id":"code-47065","kind":"paragraph","label":"47065","text":"47065 — Блоки управления топливораздаточным оборудованием\nНормативный срок службы: 5 лет.","level":3},{"id":"code-47066","kind":"paragraph","label":"47066","text":"47066 — Приборы оптико-механические и для линейно-угловых измерений\nНормативный срок службы: 12 лет.","level":3},{"id":"code-47067","kind":"paragraph","label":"47067","text":"47067 — Станки балансировочные\nНормативный срок службы: 20 лет.","level":3},{"id":"code-47068","kind":"paragraph","label":"47068","text":"47068 — Приборы и аппаратура для физических исследований и измерений (в том числе параметров атмосферы, почвы, водоемов, гидрологии, метеорологии, сейсмологии, течеискатели, используемые для поиска порывов в подземных тепловых сетях)\nНормативный срок службы: 8 лет.","level":3}]$batch161_09$::jsonb;
BEGIN
  SELECT id, jsonb_array_length(structure)
  INTO v_document_id, v_structure_length
  FROM public.legal_documents
  WHERE external_id = 'w21124359'
  LIMIT 1;

  IF v_document_id IS NULL THEN
    RAISE EXCEPTION 'Resolution 161 staging document is missing';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.legal_documents
    WHERE id = v_document_id
      AND checksum = 'ac7e28c93b6b3d1f029cec22593157d1624f9de9c7ffee1a811bd60e743b5f4b'
      AND is_published
      AND jsonb_array_length(structure) = 2349
  ) THEN
    IF (
      SELECT count(*)
      FROM jsonb_array_elements(v_chunk) expected
      WHERE NOT EXISTS (
        SELECT 1
        FROM jsonb_array_elements(
          (SELECT structure FROM public.legal_documents WHERE id = v_document_id)
        ) actual
        WHERE actual->>'id' = expected->>'id'
          AND actual = expected
      )
    ) <> 0 THEN
      RAISE EXCEPTION 'Resolution 161 finalized document differs from batch 09';
    END IF;
    RETURN;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.legal_documents
    WHERE id = v_document_id
      AND COALESCE(metadata #> '{resolution_161_import,applied_batches}', '[]'::jsonb)
        ? '09'
  ) THEN
    IF (
      SELECT count(*)
      FROM jsonb_array_elements(v_chunk) expected
      WHERE NOT EXISTS (
        SELECT 1
        FROM jsonb_array_elements(
          (SELECT structure FROM public.legal_documents WHERE id = v_document_id)
        ) actual
        WHERE actual->>'id' = expected->>'id'
          AND actual = expected
      )
    ) <> 0 THEN
      RAISE EXCEPTION 'Resolution 161 batch 09 marker exists but content differs';
    END IF;
    RETURN;
  END IF;

  IF v_structure_length <> 1573 THEN
    RAISE EXCEPTION
      'Resolution 161 batch 09 expected structure length 1573, got %',
      v_structure_length;
  END IF;

  UPDATE public.legal_documents
  SET
    structure = structure || v_chunk,
    metadata = jsonb_set(
      metadata,
      '{resolution_161_import,applied_batches}',
      COALESCE(metadata #> '{resolution_161_import,applied_batches}', '[]'::jsonb)
        || to_jsonb('09'::text),
      true
    )
  WHERE id = v_document_id;

  IF jsonb_array_length(
    (SELECT structure FROM public.legal_documents WHERE id = v_document_id)
  ) <> 1781 THEN
    RAISE EXCEPTION 'Resolution 161 batch 09 read-back failed';
  END IF;
END
